    <p class="hero-detail__notice" role="status" aria-live="polite">{{ vm.notice() }}</p>

    <hlm-tabs class="hero-detail__tabs" [tab]="vm.tab()" (tabActivated)="vm.setTab($event)">
      <hlm-tabs-list class="hero-detail__tab-list" aria-label="Hero sections">
        <button hlmTabsTrigger="overview">Overview</button>
        <button hlmTabsTrigger="powers">Powers</button>
        <button hlmTabsTrigger="missions">Missions</button>
